using UnityEngine;using UnityEngine.Rendering.HighDefinition;
public static class CaptureMotoroller {public static string Main(){var original=GameObject.Find("Motoroller - rideable");var root=Object.Instantiate(original);root.hideFlags=HideFlags.HideAndDontSave;root.transform.position+=original.transform.forward*3.5f;var rig=root.GetComponent<BicycleController>();var rest=rig.steering.localRotation;var go=new GameObject("Temporary scooter camera"){hideFlags=HideFlags.HideAndDontSave};var camera=go.AddComponent<Camera>();camera.enabled=false;go.AddComponent<HDAdditionalCameraData>();camera.fieldOfView=42;var rt=RenderTexture.GetTemporary(1400,1000,24);var previous=RenderTexture.active;var image=new Texture2D(1400,1000,TextureFormat.RGB24,false);try{foreach(int angle in new[]{0,30,-30}){rig.steering.localRotation=rest*Quaternion.Euler(0,angle,0);go.transform.position=root.transform.TransformPoint(new Vector3(2.8f,1.7f,3));go.transform.LookAt(root.transform.TransformPoint(new Vector3(0,.7f,0)));camera.targetTexture=rt;camera.Render();camera.Render();RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,1400,1000),0,0);image.Apply();System.IO.File.WriteAllBytes("output/Motoroller/Steering"+angle+".png",image.EncodeToPNG());}return "Captured neutral and both steering locks";}finally{rig.steering.localRotation=rest;camera.targetTexture=null;RenderTexture.active=previous;RenderTexture.ReleaseTemporary(rt);Object.DestroyImmediate(image);Object.DestroyImmediate(go);Object.DestroyImmediate(root);}}}


